import { Controller, HttpCode, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 결재 진행 전인 '기안' 상태에서만 수정할 수 있다 (결재대기·진행중·승인 등은 수정 불가).
const EDITABLE_STATUSES = ['기안'];

const INVALID = 'PURCHASE_REQUEST_INVALID_INPUT';

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function idText(value: unknown, label: string): string {
  const s = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(s)) {
    throw new ApiError(422, INVALID, label + ' 값이 올바르지 않습니다.');
  }
  return s;
}

@Controller('api/v1')
export class FnSfr02401Controller {
  @Put('/purchase-requests/:purchaseRequestId')
  async updatePurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idRaw = req.params['purchaseRequestId'];
    if (!/^[0-9]+$/.test(idRaw)) {
      throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
    }

    const missing: string[] = [];
    if (data['projectId'] === undefined || data['projectId'] === null || data['projectId'] === '') missing.push('프로젝트');
    if (data['budgetItemId'] === undefined || data['budgetItemId'] === null || data['budgetItemId'] === '') missing.push('예산과목');
    const title = text(data['title']);
    if (!title) missing.push('품의 제목');
    const purchaseContent = text(data['purchaseContent']);
    if (!purchaseContent) missing.push('구매 내용');
    if (data['amount'] === undefined || data['amount'] === null || String(data['amount']).trim() === '') missing.push('품의 금액');
    if (missing.length > 0) {
      throw new ApiError(422, INVALID, '필수 입력값이 누락되었습니다: ' + missing.join(', '));
    }
    if (title.length > 200) {
      throw new ApiError(422, INVALID, '품의 제목은 200자 이내로 입력하세요.');
    }
    const projectId = idText(data['projectId'], '프로젝트');
    const budgetItemId = idText(data['budgetItemId'], '예산과목');
    const amount = String(data['amount']).trim();
    if (!/^[0-9]+(\.[0-9]{1,2})?$/.test(amount) || Number(amount) <= 0) {
      throw new ApiError(422, INVALID, '품의 금액은 0보다 큰 숫자여야 합니다.');
    }

    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint)',
        { id: idRaw },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (!EDITABLE_STATUSES.includes(found[0]['approvalStatus'])) {
        throw new ApiError(409, 'PURCHASE_REQUEST_NOT_EDITABLE', '결재 진행 중이거나 완료되어 수정할 수 없습니다.');
      }
      const project = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (project.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const item = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId },
      );
      if (item.length === 0) {
        throw new ApiError(404, 'BUDGET_ITEM_NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE purchase_request SET project_id = CAST(:projectId AS bigint), budget_item_id = CAST(:budgetItemId AS bigint), title = :title, purchase_content = :purchaseContent, amount = CAST(:amount AS numeric), updated_at = now() WHERE purchase_request_id = CAST(:id AS bigint) RETURNING purchase_request_id AS "purchaseRequestId", approval_status AS "approvalStatus"',
        { id: idRaw, projectId, budgetItemId, title, purchaseContent, amount },
      );
      return rows[0];
    });
  }
}

