import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, Num, NumberInput, RefName, Select, TextInput, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02401Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 품의서만 목록에 쌓는다
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<'none' | 'create' | 'edit'>('none');
  const [target, setTarget] = useState<Row | null>(null);
  const [f, setF] = useState<Row>({});

  const set = (key: string, v: unknown) => setF((prev) => ({ ...prev, [key]: v }));

  const check = (keys: [string, string][]) => {
    const missing = keys
      .filter(([k]) => f[k] === undefined || f[k] === null || f[k] === '')
      .map(([, label]) => label);
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력하세요: ' + missing.join(', '));
    }
  };

  const close = () => {
    setMode('none');
    setTarget(null);
  };

  const openCreate = () => {
    setF({ requestType: '구매', assetInspectionRequired: '아니오' });
    setMode('create');
  };

  const openEdit = (row: Row) => {
    setF({
      title: row.title,
      projectId: row.projectId,
      budgetItemId: row.budgetItemId,
      purchaseContent: row.purchaseContent,
      amount: row.amount,
    });
    setTarget(row);
    setMode('edit');
  };

  const create = async () => {
    check([
      ['title', '품의 제목'],
      ['requestType', '품의 유형'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
      ['amount', '품의 금액'],
      ['reason', '품의 사유'],
    ]);
    const res = await call('POST', '/purchase-requests', role, {
      title: f.title,
      requestType: f.requestType,
      projectId: f.projectId,
      budgetItemId: f.budgetItemId,
      amount: f.amount,
      reason: f.reason,
      assetInspectionRequired: f.assetInspectionRequired === '예',
    });
    setRows((prev) => [
      {
        purchaseRequestId: res.purchaseRequestId,
        documentNo: res.documentNo,
        approvalStatus: res.approvalStatus,
        title: f.title,
        projectId: f.projectId,
        budgetItemId: f.budgetItemId,
        amount: f.amount,
        reason: f.reason,
        purchaseContent: '',
      },
      ...prev,
    ]);
    notify('구매품의서를 등록했습니다.');
    close();
  };

  const update = async () => {
    check([
      ['title', '품의 제목'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
      ['purchaseContent', '구매 내용'],
      ['amount', '품의 금액'],
    ]);
    const id = target?.purchaseRequestId;
    const res = await call('PUT', '/purchase-requests/' + id, role, {
      projectId: f.projectId,
      budgetItemId: f.budgetItemId,
      title: f.title,
      purchaseContent: f.purchaseContent,
      amount: f.amount,
    });
    setRows((prev) =>
      prev.map((r) =>
        r.purchaseRequestId === id
          ? {
              ...r,
              title: f.title,
              projectId: f.projectId,
              budgetItemId: f.budgetItemId,
              purchaseContent: f.purchaseContent,
              amount: f.amount,
              approvalStatus: res.approvalStatus,
            }
          : r,
      ),
    );
    notify('구매품의서를 수정했습니다.');
    close();
  };

  const submitRow = async (row: Row) => {
    try {
      const res = await call('POST', '/purchase-requests/' + row.purchaseRequestId + '/submit', role);
      setRows((prev) =>
        prev.map((r) =>
          r.purchaseRequestId === row.purchaseRequestId ? { ...r, approvalStatus: res.approvalStatus } : r,
        ),
      );
      notify('결재를 상신했습니다.');
    } catch (e) {
      notify((e as Error).message);
    }
  };

  const count = (statuses: string[]) => rows.filter((r) => statuses.includes(String(r.approvalStatus))).length;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리한 품의서', rows.length],
            ['기안', count(['기안'])],
            ['결재 진행', count(['결재대기', '진행중'])],
            ['승인·완료', count(['승인', '완료'])],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>구매품의서</h2>
        <Band total={rows.length}>
          <button onClick={openCreate}>품의서 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty='이 화면에서 처리한 품의서가 없습니다.'
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'title', label: '품의 제목' },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r.projectId} /> },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table='budget_item' role={role} value={r.budgetItemId} /> },
            { key: 'amount', label: '품의 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                r.approvalStatus === '기안' ? (
                  <span>
                    <button onClick={() => openEdit(r)}>수정</button>
                    <button onClick={() => submitRow(r)}>상신</button>
                  </span>
                ) : null,
            },
          ]}
        />
      </section>
      {mode === 'create' && (
        <Drawer title='구매품의서 작성' onClose={close}>
          <Form onSubmit={create} submit='등록'>
            <Field label='품의 제목' required wide>
              <TextInput value={f.title} onChange={(v) => set('title', v)} />
            </Field>
            <Field label='품의 유형' required>
              <Select
                value={f.requestType}
                onChange={(v) => set('requestType', v)}
                options={[['구매', '구매'], ['지출', '지출']]}
              />
            </Field>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={f.projectId} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_item' role={role} value={f.budgetItemId} onChange={(v) => set('budgetItemId', v)} />
            </Field>
            <Field label='품의 금액' required>
              <NumberInput value={f.amount} onChange={(v) => set('amount', v)} />
            </Field>
            <Field label='자산 검수 여부'>
              <Select
                value={f.assetInspectionRequired}
                onChange={(v) => set('assetInspectionRequired', v)}
                options={[['아니오', '아니오'], ['예', '예']]}
              />
            </Field>
            <Field label='품의 사유' required wide>
              <TextInput multiline value={f.reason} onChange={(v) => set('reason', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && (
        <Drawer title='구매품의서 수정' onClose={close}>
          <Form onSubmit={update} submit='수정'>
            <Field label='품의 제목' required wide>
              <TextInput value={f.title} onChange={(v) => set('title', v)} />
            </Field>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={f.projectId} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_item' role={role} value={f.budgetItemId} onChange={(v) => set('budgetItemId', v)} />
            </Field>
            <Field label='품의 금액' required>
              <NumberInput value={f.amount} onChange={(v) => set('amount', v)} />
            </Field>
            <Field label='구매 내용' required wide>
              <TextInput multiline value={f.purchaseContent} onChange={(v) => set('purchaseContent', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
